/// Where a code writes and what: a word, or injected instructions (offset, word) among its
/// `len` words.
pub struct Site {
    pub addr: u32,
    pub code: Code,
}

pub enum Code {
    Word(u32),
    Inject {
        len: u32,
        words: &'static [(u32, u32)],
    },
}

/// A port of `function` for the codes at `sites`.
pub struct Patched {
    pub function: u32,
    pub name: &'static str,
    pub sites: &'static [Site],
    pub port: fn(&Ctx),
}

/// A port of the code at `site` entered `offset` into its injected instructions, where
/// other code calls it.
pub struct Entry {
    pub site: u32,
    pub offset: u32,
    pub code: Code,
    pub port: fn(&Ctx),
}

